<script>
(()=>{const modal=document.getElementById('zone-modal'),form=document.getElementById('zone-form'),method=document.getElementById('zone-method'),title=document.getElementById('modal-title'),canvas=document.getElementById('map-canvas'),notice=document.getElementById('layout-status'),page=document.getElementById('club-map-page'),toggle=document.getElementById('editor-toggle'),hint=document.getElementById('editor-hint'),csrf=@json(csrf_token());const fields={name:document.getElementById('zone-name'),description:document.getElementById('zone-description'),capacity:document.getElementById('zone-capacity'),icon:document.getElementById('zone-icon'),theme:document.getElementById('zone-theme'),status:document.getElementById('zone-status'),order:document.getElementById('zone-order')};const open=()=>modal.classList.add('open'),close=()=>modal.classList.remove('open');toggle.addEventListener('change',()=>{page.classList.toggle('edit-mode',toggle.checked);hint.textContent=toggle.checked?'Перетаскивайте карточки мышью. Размер меняется за зелёный угол снизу справа.':'Включите редактор, чтобы изменить карту клуба.'});
document.getElementById('add-zone').addEventListener('click',()=>{form.action=@json(route('club-map.store'));method.value='POST';title.textContent='Добавить зону';form.reset();fields.order.value=document.querySelectorAll('.cm-zone').length*10;open()});document.querySelectorAll('.edit-zone').forEach(button=>button.addEventListener('click',()=>{form.action=@json(url('/club-map'))+'/'+button.dataset.id;method.value='PUT';title.textContent='Редактировать зону';Object.keys(fields).forEach(key=>fields[key].value=button.dataset[key]??'');open()}));document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',close));modal.addEventListener('click',event=>{if(event.target===modal)close()});
const collides=(card,x,y,width,height)=>Array.from(document.querySelectorAll('.cm-zone')).some(other=>other!==card&&x<parseInt(other.style.left)+other.offsetWidth+20&&x+width+20>parseInt(other.style.left)&&y<parseInt(other.style.top)+other.offsetHeight+20&&y+height+20>parseInt(other.style.top));const save=async(card,previous)=>{notice.classList.add('show');const payload={position_x:parseInt(card.style.left),position_y:parseInt(card.style.top),width:Math.round(card.offsetWidth),height:Math.round(card.offsetHeight)};const response=await fetch(card.dataset.saveUrl,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify(payload)});if(!response.ok)Object.entries(previous).forEach(([property,value])=>card.style[property]=value+'px');notice.textContent=response.ok?'Расположение сохранено':'Карточки не могут пересекаться';setTimeout(()=>{notice.classList.remove('show');notice.textContent='Сохраняем расположение…'},1200)};
document.querySelectorAll('.cm-zone').forEach(card=>{card.addEventListener('pointerdown',event=>{if(!page.classList.contains('edit-mode')||event.target.closest('button,form,.cm-resize,.cm-computer'))return;event.preventDefault();card.setPointerCapture(event.pointerId);card.classList.add('dragging');const grid=20,startX=event.clientX,startY=event.clientY,left=parseInt(card.style.left),top=parseInt(card.style.top);const move=e=>{const nextX=Math.max(0,Math.round((left+e.clientX-startX)/grid)*grid),nextY=Math.max(0,Math.round((top+e.clientY-startY)/grid)*grid),blocked=collides(card,nextX,nextY,card.offsetWidth,card.offsetHeight);card.classList.toggle('blocked',blocked);if(!blocked){card.style.left=nextX+'px';card.style.top=nextY+'px';canvas.style.height=Math.max(430,nextY+card.offsetHeight+30)+'px'}};const end=()=>{card.classList.remove('dragging','blocked');card.removeEventListener('pointermove',move);card.removeEventListener('pointerup',end);save(card,{left,top})};card.addEventListener('pointermove',move);card.addEventListener('pointerup',end)});const handle=card.querySelector('.cm-resize');handle.addEventListener('pointerdown',event=>{if(!page.classList.contains('edit-mode'))return;event.preventDefault();event.stopPropagation();handle.setPointerCapture(event.pointerId);card.classList.add('resizing');const grid=20,startX=event.clientX,startY=event.clientY,width=card.offsetWidth,height=card.offsetHeight;const move=e=>{const nextWidth=Math.max(180,Math.round((width+e.clientX-startX)/grid)*grid),nextHeight=Math.max(140,Math.round((height+e.clientY-startY)/grid)*grid),blocked=collides(card,parseInt(card.style.left),parseInt(card.style.top),nextWidth,nextHeight);card.classList.toggle('blocked',blocked);if(!blocked){card.style.width=nextWidth+'px';card.style.height=nextHeight+'px';canvas.style.height=Math.max(430,parseInt(card.style.top)+nextHeight+30)+'px'}};const end=()=>{card.classList.remove('resizing','blocked');handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);save(card,{width,height})};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end)})});
document.querySelectorAll('.cm-computer').forEach(computer=>computer.addEventListener('pointerdown',event=>{if(!page.classList.contains('edit-mode'))return;event.preventDefault();event.stopPropagation();const area=computer.parentElement,gridX=47,gridY=42,offset=5;computer.setPointerCapture(event.pointerId);computer.classList.add('moving');const startX=event.clientX,startY=event.clientY,left=parseInt(computer.style.left),top=parseInt(computer.style.top);const move=e=>{const limitX=Math.max(0,area.scrollWidth-computer.offsetWidth),limitY=Math.max(0,area.scrollHeight-computer.offsetHeight),maxX=limitX>=offset?offset+Math.floor((limitX-offset)/gridX)*gridX:0,maxY=limitY>=offset?offset+Math.floor((limitY-offset)/gridY)*gridY:0,snapX=offset+Math.round((left+e.clientX-startX-offset)/gridX)*gridX,snapY=offset+Math.round((top+e.clientY-startY-offset)/gridY)*gridY,nextX=Math.min(maxX,Math.max(offset,snapX)),nextY=Math.min(maxY,Math.max(offset,snapY)),occupied=Array.from(area.querySelectorAll('.cm-computer')).some(item=>item!==computer&&parseInt(item.style.left)===nextX&&parseInt(item.style.top)===nextY);computer.classList.toggle('blocked',occupied);if(!occupied){computer.style.left=nextX+'px';computer.style.top=nextY+'px'}};const end=async()=>{computer.classList.remove('moving','blocked');computer.removeEventListener('pointermove',move);computer.removeEventListener('pointerup',end);notice.classList.add('show');const response=await fetch(computer.dataset.saveUrl,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({position_x:parseInt(computer.style.left),position_y:parseInt(computer.style.top)})});if(!response.ok){computer.style.left=left+'px';computer.style.top=top+'px'}notice.textContent=response.ok?'Место ПК сохранено':'Ячейка занята';setTimeout(()=>{notice.classList.remove('show');notice.textContent='Сохраняем расположение…'},1200)};computer.addEventListener('pointermove',move);computer.addEventLis